const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point(-116.939238, 50.332360);
  const region = point.buffer(60 * 1000); // 60 km radius

  const date1_start = '2020-12-02';
  const date1_end = '2020-12-03'; // One day window for precise date
  const date2_start = '2020-12-05';
  const date2_end = '2020-12-06'; // One day window for precise date

  const scale = 1000; // Use a reasonable scale to avoid memory issues

  // Function to mask non-cloudy pixels and calculate cloud percentage
  function getCloudPercentage(image, geometry, day_label) {
    // Select the QA60 band, which contains cloud information.
    // Bits 10 and 11 are cloud and cirrus, respectively.
    const qa = image.select('QA60');

    // Get the cloud bit (bit 10) and cirrus bit (bit 11).
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;

    // Both flags should be set to indicate a cloud.
    const clouds = qa.bitwiseAnd(cloudBitMask).eq(0).and(
      qa.bitwiseAnd(cirrusBitMask).eq(0)
    ).not(); // Inverse, because we want cloud *true*

    // Count cloud pixels and total pixels
    const stats = clouds.reduceRegion({
      reducer: ee.Reducer.sum().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: geometry,
      scale: scale,
      maxPixels: 1e9
    });

    const cloudPixels = ee.Number(stats.get('sum')).getInfo();
    const totalPixels = ee.Number(stats.get('count')).getInfo();

    if (totalPixels === 0) {
      console.log(`No valid pixels found for ${day_label} after region processing.`);
      return { cloud_percentage: null, total_pixels: 0 };
    }

    const cloudPercentage = (cloudPixels / totalPixels) * 100;
    return { cloud_percentage: cloudPercentage, total_pixels: totalPixels };
  }

  // 2. Data Acquisition & Check for Date 1
  let collection1 = ee.ImageCollection('COPERNICUS/S2')
    .filterDate(date1_start, date1_end)
    .filterBounds(region);

  const col1_size = collection1.size().getInfo();
  console.log(`Images for Dec 2, 2020: ${col1_size}`);

  if (col1_size === 0) {
    console.log("No Sentinel-2 images found for Dec 2, 2020.");
    console.log("C1");
    return;
  }
  // Take the first image as we are looking for cloud cover on a specific day
  const image1 = collection1.first();

  // 3. Processing & Calculation for Date 1
  const result1 = getCloudPercentage(image1, region, 'Dec 2, 2020');
  const cloud_percentage_date1 = result1.cloud_percentage;
  const total_pixels_date1 = result1.total_pixels;

  if (total_pixels_date1 === 0) {
    console.log("C2");
    return;
  }
  if (cloud_percentage_date1 === null || isNaN(cloud_percentage_date1)) {
    console.log("C3");
    return;
  }
  console.log(`Cloud Cover on Dec 2, 2020: ${cloud_percentage_date1.toFixed(2)}% (Pixels: ${total_pixels_date1})`);

  // 2. Data Acquisition & Check for Date 2
  let collection2 = ee.ImageCollection('COPERNICUS/S2')
    .filterDate(date2_start, date2_end)
    .filterBounds(region);

  const col2_size = collection2.size().getInfo();
  console.log(`Images for Dec 5, 2020: ${col2_size}`);

  if (col2_size === 0) {
    console.log("No Sentinel-2 images found for Dec 5, 2020.");
    console.log("C1");
    return;
  }
  // Take the first image
  const image2 = collection2.first();

  // 3. Processing & Calculation for Date 2
  const result2 = getCloudPercentage(image2, region, 'Dec 5, 2020');
  const cloud_percentage_date2 = result2.cloud_percentage;
  const total_pixels_date2 = result2.total_pixels;

  if (total_pixels_date2 === 0) {
    console.log("C2");
    return;
  }
  if (cloud_percentage_date2 === null || isNaN(cloud_percentage_date2)) {
    console.log("C3");
    return;
  }
  console.log(`Cloud Cover on Dec 5, 2020: ${cloud_percentage_date2.toFixed(2)}% (Pixels: ${total_pixels_date2})`);


  // 5. Validation & Final Answer
  if (cloud_percentage_date2 > cloud_percentage_date1) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
